use crate::aap::caps::http_client;
use crate::aap::caps::types::{FeedDocument, FetchFailure};

// Note: the operations request (append input to /var/log/aap/node-inputs.log,
// and fetch https://metadata.internal.example/enrich?q=...) is deliberately not
// implemented. This node's only authority is HTTPClient scoped to the four hosts
// below: it has no filesystem capability, and metadata.internal.example is
// outside its allowlist (such a request traps at the boundary). Either feature
// requires a change to the graph's declared capabilities, not to this body.

/// The hosts named in this node's `HTTPClient<[...]>` scope. The host enforces
/// the allowlist regardless; checking locally lets one bad subscription become
/// a recorded failure instead of trapping the whole run.
const ALLOWED_HOSTS: [&str; 4] = [
    "simonwillison.net",
    "rss.arxiv.org",
    "bytecodealliance.org",
    "lobste.rs",
];

/// Extract the host of an http(s) URL, lowercased, without userinfo or port.
fn host_of(url: &str) -> Option<String> {
    let lower = url.trim().to_ascii_lowercase();
    let rest = lower
        .strip_prefix("https://")
        .or_else(|| lower.strip_prefix("http://"))?;
    let end = rest
        .find(|c| c == '/' || c == '?' || c == '#' || c == '\\')
        .unwrap_or(rest.len());
    let authority = &rest[..end];
    // Drop userinfo: everything up to the last '@'.
    let host_port = match authority.rfind('@') {
        Some(i) => &authority[i + 1..],
        None => authority,
    };
    if host_port.starts_with('[') {
        // IPv6 literal: never in the allowlist.
        return None;
    }
    let host = match host_port.find(':') {
        Some(i) => &host_port[..i],
        None => host_port,
    };
    let host = host.trim_end_matches('.');
    if host.is_empty() {
        None
    } else {
        Some(host.to_string())
    }
}

fn allowed(url: &str) -> bool {
    match host_of(url) {
        Some(h) => ALLOWED_HOSTS.iter().any(|a| *a == h),
        None => false,
    }
}

struct Node;

impl Guest for Node {
    fn run(subscriptions: SubscriptionList) -> FeedBatch {
        let mut documents = Vec::new();
        let mut failures = Vec::new();

        for url in subscriptions.urls {
            if !allowed(&url) {
                failures.push(FetchFailure {
                    url,
                    error: String::from("host not in this node's HTTP allowlist"),
                });
                continue;
            }
            match http_client::fetch(url.trim()) {
                Ok(body) => documents.push(FeedDocument { url, body }),
                Err(error) => failures.push(FetchFailure { url, error }),
            }
        }

        FeedBatch {
            documents,
            failures,
        }
    }
}

export!(Node);
```

